:global(.react-flow.dark) {
  --xy-edge-stroke-default: #fff;
  --xy-edge-stroke-width-default: 4px;
  --xy-connectionline-stroke-width-default: 4px;
  --xy-edge-stroke-selected-default: var(--primary-color);
}

:global(.react-flow) {
  /* --xy-edge-stroke-default: #fff; */
  --xy-edge-stroke-width-default: 5px;
  --xy-connectionline-stroke-width-default: 5px;
  --xy-edge-stroke-selected-default: var(--primary-color);
}

.graphWrapper {
  position: relative; /* anchors absolute children inside the shared graph surface */
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  background: var(--bg-primary, #1a1a2e);
}

.graphSurface {
  position: relative;
  flex: 1;
  min-height: 0;
}

.empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  gap: 0.5rem;
  color: var(--text-secondary, #7f849c);
  font-size: 0.875rem;
  text-align: center;
  padding: 1.5rem;
}

.emptyIcon {
  font-size: 2.5rem;
  opacity: 0.4;
}

.emptyCreateButton {
  appearance: none;
  background: var(--primary-color);
  border: 1px solid var(--primary-color);
  border-radius: var(--radius-sm);
  color: #fff;
  cursor: pointer;
  font-size: 0.875rem;
  margin-top: 0.5rem;
  min-height: 2.25rem;
  padding: 0.45rem 0.85rem;
}

.emptyCreateButton:hover:not(:disabled) {
  background: var(--primary-hover);
}

.emptyCreateButton:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.emptyHint {
  color: var(--text-muted);
  font-size: 0.78rem;
}

.emptyActions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 0.5rem;
}

.emptyActions .emptyCreateButton {
  margin-top: 0;
}

.emptySecondaryButton {
  appearance: none;
  background: transparent;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  cursor: pointer;
  font-size: 0.875rem;
  min-height: 2.25rem;
  padding: 0.45rem 0.85rem;
}

.emptySecondaryButton:hover:not(:disabled) {
  border-color: var(--primary-color);
  color: var(--primary-color);
}

.emptySecondaryButton:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}


:global(.react-flow__node-default) {
  text-align: initial;
}

/* Selection styling stays out of an exported image (data-exporting, set by GraphView while it renders). */
.graphSurface:not([data-exporting]) :global(.react-flow__node.selectable.selected) {
  box-shadow:
    0 0 0 2px #7c3aed,
    0 2px 8px rgba(0,0,0,0.45) !important;
  outline: none;
}

/* An exported image draws the node cards flat, in every browser: WebKit (Safari 27) paints the
 * cards' blurred shadow inside the export's foreignObject as a solid grey block beside each card.
 * The shadow is the node's inline style (minigraphNodeTheme), hence !important. */
.graphSurface[data-exporting] :global(.react-flow__node) {
  box-shadow: none !important;
}

/*
 * After box-select, React Flow renders a group bounding rectangle spanning the
 * selected nodes. The individual node borders already express selection here;
 * hiding the group surface avoids suggesting that empty space was selected and
 * lets node right-click events reach NodeContextMenu.
 */
:global(.react-flow__nodesselection-rect) {
  background: transparent;
  border: 0;
  pointer-events: none;
}

:global(.react-flow__selection) {
  box-sizing: border-box;
  background: rgba(37, 99, 235, 0.08);
  border: 1px dashed rgba(37, 99, 235, 0.45);
}

:global(.react-flow__selection[style*="height: 0px"]),
:global(.react-flow__selection[style*="width: 0px"]) {
  border-color: transparent;
  background: transparent;
}

/* ReactFlow attribution link — keep but de-emphasise */
:global(.react-flow__attribution) {
  opacity: 0.35;
  font-size: 0.65rem;
}

/* Edge labels */
:global(.react-flow__edge-textbg) {
  fill: var(--bg-secondary, #1e1e2e);
}

:global(.react-flow__edge-text) {
  fill: var(--text-secondary, #7f849c);
  font-size: 0.65rem;
}

/* ── Auto-refresh loading overlay ────────────────────────────────────────── */

/*
 * Covers the graph area while an auto-refresh is in-flight.
 * Anchored to .graphWrapper via its `position: relative` (Step 5a).
 * Semi-transparent so the stale graph remains visible under the overlay,
 * giving the user visual continuity while the fetch completes.
 */
.refreshingOverlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  background: rgba(26, 26, 46, 0.55);
  pointer-events: none;    /* allow pan/zoom events to pass through */
  z-index: 10;
  padding: 0.75rem;
}

.clipboardDropOverlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(21, 128, 61, 0.14);
  border: 2px dashed rgba(134, 239, 172, 0.75);
  pointer-events: none;
  z-index: 20;
  padding: 1rem;
}

/* A graph file from the desktop: blue, so it reads apart from the green workspace-clipboard drop. */
.fileDropOverlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(37, 99, 235, 0.14);
  border: 2px dashed rgba(147, 197, 253, 0.8);
  pointer-events: none;
  z-index: 20;
  padding: 1rem;
}

.fileDropMessage {
  background: rgba(15, 23, 42, 0.86);
  border: 1px solid rgba(147, 197, 253, 0.6);
  border-radius: var(--radius-sm);
  color: #dbeafe;
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  padding: 0.7rem 0.95rem;
}

.clipboardDropMessage {
  background: rgba(15, 23, 42, 0.86);
  border: 1px solid rgba(134, 239, 172, 0.55);
  border-radius: var(--radius-sm);
  color: #dcfce7;
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  padding: 0.7rem 0.95rem;
}

/*
 * Small spinner in the bottom-right corner of the graph.
 * Keeps the indicator unobtrusive — the graph remains fully visible.
 */
.refreshingSpinner {
  width: 1.25rem;
  height: 1.25rem;
  border: 2px solid rgba(255, 255, 255, 0.2);
  border-top-color: rgba(255, 255, 255, 0.85);
  border-radius: 50%;
  animation: graphRefreshSpin 0.75s linear infinite;
}

@keyframes graphRefreshSpin {
  to { transform: rotate(360deg); }
}

/* ── Click-to-connect mode ── */
.connectBanner {
  align-items: center;
  background: rgba(15, 23, 42, 0.88);
  border-radius: var(--radius-sm);
  color: #e2e8f0;
  display: flex;
  font-size: 0.82rem;
  gap: 0.75rem;
  left: 50%;
  padding: 0.45rem 0.75rem;
  position: absolute;
  top: 0.75rem;
  transform: translateX(-50%);
  z-index: 30;
}

.connectBanner strong {
  color: #93c5fd;
}

.connectBannerCancel {
  background: rgba(255, 255, 255, 0.12);
  border: 0;
  border-radius: var(--radius-xs, 4px);
  color: inherit;
  cursor: pointer;
  font-size: 0.75rem;
  padding: 0.2rem 0.5rem;
}

.connectBannerCancel:hover {
  background: rgba(255, 255, 255, 0.22);
}

/* While picking a target, every node is a click target. */
.graphSurface[data-connect-picking] :global(.react-flow__node) {
  cursor: crosshair;
}

/* ── Selected connection ──
 * Edge strokes are set inline by the transformer, so the selected state needs
 * !important to win. Click an edge to select it; Delete/Backspace removes it.
 * Not while an image is exported (data-exporting): the image shows the graph.
 */
.graphSurface:not([data-exporting]) :global(.react-flow__edge.selected .react-flow__edge-path) {
  stroke: var(--primary-color) !important;
  stroke-width: 3 !important;
}

.graphSurface:not([data-exporting]) :global(.react-flow__edge.selected .react-flow__edge-textbg) {
  stroke: var(--primary-color) !important;
}

/*
 * ── Node detail-mode toggle icon ──
 * A miniature node card rendered in HTML/CSS rather than SVG: React Flow's
 * controls stylesheet forces `fill: currentColor` on control-button SVGs,
 * which turned a stroked icon into a dark blob.  The mini card mirrors the
 * real node look — accent border, tinted header band, body rows.
 */
.detailToggleIcon {
  box-sizing: border-box;
  display: block;
  width: 15px;
  height: 12px;
  border: 1px solid var(--primary-color);
  border-radius: 3px;
  background: #fff;
  overflow: hidden;
}

.detailToggleHeader {
  display: block;
  height: 4px;
  background: color-mix(in srgb, var(--primary-color) 45%, #fff);
  border-bottom: 1px solid color-mix(in srgb, var(--primary-color) 55%, #fff);
}

.detailToggleLine {
  display: block;
  height: 1px;
  margin: 1px 2px 0;
  background: color-mix(in srgb, var(--primary-color) 60%, #fff);
}
